  <input id='filters' type='checkbox' class='toggle' />
  <aside class='rail' aria-label='Filters'>
    <nav>...</nav>
  </aside>
  <main class='tiles'>
    <section class='tile' data-value='1234'>
      <h3>Revenue</h3>
      <div class='value'>1,234</div>
      <div class='sparkline' aria-hidden='true'></div>
    </section>
    <section class='tile' data-value='5678'>
      <h3>Costs</h3>
